/** D125: maximum back hold after cancellation starts; cleanup lifetime belongs to the app. */
val SbCancelBackHold = 5.seconds

/** Remaining foreground hold; saved across recreation, independent of label/progress updates. */
@Stable
class SbCancelBackHoldState internal constructor(remaining: Long) {
    var remainingMillis by mutableLongStateOf(remaining)
        internal set
    private val heldState = derivedStateOf { remainingMillis > 0L }
    val held: Boolean get() = heldState.value
}

/** Provide one instance around the screen to share its clock with the action zone and the app's back arrow. */
val LocalSbCancelBackHold = staticCompositionLocalOf<SbCancelBackHoldState?> { null }

@Composable
fun rememberSbCancelBackHold(cancelling: Boolean): SbCancelBackHoldState {
    val hold = rememberSaveable(cancelling, saver = SbHoldSaver<SbCancelBackHoldState, Long>(
        save = { it.remainingMillis }, restore = { SbCancelBackHoldState(it) },
    )) { SbCancelBackHoldState(if (cancelling) SbCancelBackHold.inWholeMilliseconds else 0L) }
    // A saved remainder belongs only to an active cancellation, including the first restored frame.
    if (!cancelling) hold.remainingMillis = 0L
    LaunchedEffect(hold, cancelling) {
        if (!cancelling) return@LaunchedEffect
        // delay in 100 ms steps, not a frame loop: no frames for 5 s, and the saved remainder is at most 100 ms stale
        while (hold.held) {
            val step = minOf(100L, hold.remainingMillis)
            delay(step)
            hold.remainingMillis = (hold.remainingMillis - step).coerceAtLeast(0L)
        }
    }
    return hold
}


