@Immutable
sealed interface SbActionState {
    /** Nothing runs: the normal label. */
    data object Idle : SbActionState

    /** Work runs: [label] says what („Wird angelegt …“); [fraction] 0..1 when the share is known, else null. */
    class Busy(val label: String, val fraction: Float? = null, val cancel: SbCancelAction? = null, val cancelling: Boolean = false) : SbActionState {
        @Deprecated("Binary bridge before cancelling", level = DeprecationLevel.HIDDEN)
        constructor(label: String, fraction: Float? = null, cancel: SbCancelAction? = null) : this(label, fraction, cancel, false)
        @Deprecated("Binary bridge before cancel", level = DeprecationLevel.HIDDEN)
        constructor(label: String, fraction: Float? = null) : this(label, fraction, null)
        operator fun component1(): String = label
        operator fun component2(): Float? = fraction
        fun copy(label: String = this.label, fraction: Float? = this.fraction, cancel: SbCancelAction? = this.cancel, cancelling: Boolean = this.cancelling): Busy = Busy(label, fraction, cancel, cancelling)
        @Deprecated("Binary bridge before cancelling", level = DeprecationLevel.HIDDEN)
        fun copy(label: String = this.label, fraction: Float? = this.fraction, cancel: SbCancelAction? = this.cancel): Busy = Busy(label, fraction, cancel, cancelling)
        @Deprecated("Binary bridge before cancel", level = DeprecationLevel.HIDDEN)
        fun copy(label: String = this.label, fraction: Float? = this.fraction): Busy = Busy(label, fraction, cancel, cancelling)
        override fun equals(other: Any?): Boolean = other is Busy && label == other.label && fraction == other.fraction && cancel == other.cancel && cancelling == other.cancelling
        override fun hashCode(): Int = 31 * (31 * (31 * label.hashCode() + (fraction?.hashCode() ?: 0)) + (cancel?.hashCode() ?: 0)) + cancelling.hashCode()
        override fun toString(): String = "Busy(label=$label, fraction=$fraction, cancel=$cancel, cancelling=$cancelling)"
    }

    /** Finished: the check icon and [label] for x.primaryActionDoneDwell ms, then the app sets Idle again. */
    data class Done(val label: String) : SbActionState

    /**
     * Failed: [reason] as a sentence beside the action, the action reads [retryLabel] (null = the table's word);
     * [details] the technical text under „Details“ (D102 (23)), null = none. [attempt] counts the tries when the app has
     * no state between them: a new value is a new failure, and its sentence shows from its start (CHECKS.md §93).
     */
    data class Failed(val reason: String, val retryLabel: String? = null, val details: String? = null, val attempt: Int = 0) : SbActionState {
        @Deprecated("Binary bridge before attempt", level = DeprecationLevel.HIDDEN)
