        @Deprecated("Binary bridge before attempt", level = DeprecationLevel.HIDDEN)
        fun copy(reason: String = this.reason, retryLabel: String? = this.retryLabel, details: String? = this.details): Failed = Failed(reason, retryLabel, details, attempt)
    }
