/**
 * The primary action (Hauptaktion): lime fill, ink label, 2 dp outline, radius 8, never filled in any other colour.
 * Use it through SbScreen(primaryAction = …); there is at most one per view (D39). [state] shows its progress (D48).
 * [haptics] = false: the app's „Vibration“ switch is off, the success pulse stays silent (D105 (24)).
 */
@Composable
fun SbPrimaryAction(
    text: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    icon: ImageVector? = null,
    enabled: Boolean = true,
    state: SbActionState = SbActionState.Idle,
    haptics: Boolean = true,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val pulse = rememberSbHaptics(haptics)
    LaunchedEffect(state) { if (state is SbActionState.Done) pulse.success() }
    val busy = state is SbActionState.Busy
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    // the action keeps the focus it has when the work starts: without it the next Enter would act on another control (CHECKS.md §88)
    var focused by remember { mutableStateOf(false) }
    // a press belongs to the state it began in: a key held through the end of the work does not act (CHECKS.md §89)
    val busyNow by rememberUpdatedState(busy)
    var pressedBusy by remember { mutableStateOf(false) }
    LaunchedEffect(interaction) {
        interaction.interactions.collect {
            if (it is PressInteraction.Press) pressedBusy = busyNow
            // no click follows a cancelled press
            if (it is PressInteraction.Cancel) pressedBusy = false
        }
    }
    val fill = when {
        !enabled -> c.surfaceSunken
        pressed && !busy -> c.primaryActionPressed
        hovered && !busy -> c.primaryActionHover
        else -> c.primaryAction
    }
    val edge = if (enabled) c.primaryActionOutline else c.borderStrong
    val label = if (enabled) c.onPrimaryAction else c.textMuted
    val shape = t.shapes.control
    val shownText = when (state) {
        SbActionState.Idle -> text
        is SbActionState.Busy -> state.label
        is SbActionState.Done -> state.label
        is SbActionState.Failed -> state.retryLabel ?: sbMessages().retry
    }
    val shownIcon = when (state) {
        SbActionState.Idle -> icon
        is SbActionState.Done -> SebaroIcons.Outline.Check
        else -> null
    }
    Box(
        modifier
            .sbFocusRing(interaction, t.radius.control)
            .heightIn(min = t.size.controlLg)
            .clip(shape)
            .background(fill, shape)
            .border(t.x.primaryActionOutlineWidth, edge, shape)
            .onFocusChanged { focused = it.isFocused }
            .clickable(
                interactionSource = interaction,
                indication = null,
                enabled = enabled && (!busy || focused),
                role = Role.Button,
                onClick = {
                    // read and cleared here: a click without a press (TalkBack's) comes after it (CHECKS.md §93)
                    val fromBusy = pressedBusy
                    pressedBusy = false
                    if (!busy && !fromBusy) onClick()
                },
            )
            .then(if (busy && focused) Modifier.semantics { disabled() } else Modifier),
        contentAlignment = Alignment.Center,
    ) {
        // D99 (1): the label keeps the busy bar's height, the outline and a 4 dp gap (space.s1; 2026-11-01, provisional,
        // agent: without it the bar touched the descenders of a second line at font scale 2.0) free above and below it
        // in every state, so at a large font scale the action grows and the bar clears the descenders (at font scale 1
        // the 56 dp hold it), and the height does not jump when the work starts
        Row(
            Modifier
                .heightIn(min = t.size.controlLg)
                .padding(
                    horizontal = t.space.s6,
                    vertical = t.x.primaryActionOutlineWidth + t.x.primaryActionProgressHeight + t.space.s1,
                ),
            horizontalArrangement = Arrangement.spacedBy(t.spacing.inline, Alignment.CenterHorizontally),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            if (shownIcon != null) {
                SbActionLabel(shownIcon, shownText, label)
            } else {
                SbWrapText(shownText, SebaroTheme.typography.bodyStrong, label, center = true)
            }
        }
        // inside the 2 dp outline, as on the web (the bar sits in the padding box): drawn under it, the outline would
        // cover a third of the bar (seen in the render, §18)
        if (state is SbActionState.Busy) {
            SbActionProgressBar(state.fraction, label, Modifier.matchParentSize().padding(t.x.primaryActionOutlineWidth))
        }
    }
}

/** The 6 dp ink bar along the bottom edge of the busy primary action (D48). */
@Composable
private fun SbActionProgressBar(fraction: Float?, color: Color, modifier: Modifier) {
    val t = SebaroTheme.tokens
    val height = t.x.primaryActionProgressHeight
    Box(modifier) {
        when {
            fraction != null -> {
                val shown by animateFloatAsState(
                    fraction.coerceIn(0f, 1f),
                    tween(t.motion.durationMedium, easing = LinearEasing),
                    label = "progress",
                )
                Box(Modifier.align(Alignment.BottomStart).fillMaxWidth(shown).height(height).background(color))
            }
            sbReduceMotion() -> {
                Box(Modifier.align(Alignment.BottomStart).fillMaxWidth().height(height).alpha(0.4f).background(color))
            }
            else -> {
                val rtl = LocalLayoutDirection.current == LayoutDirection.Rtl
                val sweep = rememberInfiniteTransition(label = "sweep")
                val position by sweep.animateFloat(
                    initialValue = -1f,
                    targetValue = 3f,
                    animationSpec = infiniteRepeatable(tween(t.x.primaryActionProgressPeriod, easing = t.motion.easingStandard)),
                    label = "sweep",
                )
                Box(
                    Modifier
                        .align(Alignment.BottomStart)
                        .fillMaxWidth(0.34f)
                        .height(height)
                        .graphicsLayer { translationX = (if (rtl) -position else position) * size.width }
                        .background(color),
                )
            }
        }
    }
}

