/**
 * A request to move the focus to the screen's primary action (SbScreen's primaryActionFocus, §4; 2026-11-01,
 * provisional, agent). [request] may come before the action exists (the last entry removed, the add action not drawn
 * yet): it waits and is served once the action is laid out. Keyboard mode: the input focus moves there. Touch mode: a
 * button takes no input focus there (as a View not focusable in touch mode), so it moves only while TalkBack explores
 * by touch; TalkBack's focus follows the focused node. A sighted touch user's screen does not change.
 */
@Stable
class SbActionFocus {
    internal var asked by mutableIntStateOf(0)
    internal var served = 0

    /** Moves the focus to the primary action now, or as soon as it is laid out. */
    fun request() {
        asked++
    }
}

/** An [SbActionFocus] kept across recompositions. */
@Composable
fun rememberSbActionFocus(): SbActionFocus = remember { SbActionFocus() }

/** SbPrimaryActionBar with [focus] on the button (SbScreen's primaryActionFocus, §4); not public. */
@Composable
internal fun SbPrimaryActionBarFocus(
    text: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    icon: ImageVector? = null,
    enabled: Boolean = true,
    hint: String? = null,
    state: SbActionState = SbActionState.Idle,
    haptics: Boolean = true,
    focus: SbActionFocus? = null,
    secondaryAction: (@Composable () -> Unit)? = null,
) {
    val t = SebaroTheme.tokens
    val c = SebaroTheme.colors
    val requester = remember { FocusRequester() }
    val input = LocalInputModeManager.current
    val context = LocalContext.current
    // true from a request in touch mode with TalkBack until the button loses the focus again
    var touchFocus by remember { mutableStateOf(false) }
    var hadFocus by remember { mutableStateOf(false) }
    val cancelling = state is SbActionState.Busy && state.cancelling
    val localHold = LocalSbCancelBackHold.current
    val hold = localHold ?: rememberSbCancelBackHold(cancelling)
    val cancelBackHeld = cancelling && hold.held
    var announcedWork by remember { mutableStateOf<String?>(null) }
    val workLabel = when (state) {
        is SbActionState.Busy -> state.label
        is SbActionState.Done -> state.label
        else -> null
    }
    LaunchedEffect(workLabel, state is SbActionState.Busy, cancelling) {
        announcedWork = null
        if (state is SbActionState.Busy && !state.cancelling) delay(1000)
        announcedWork = workLabel
    }
    val asked = focus?.asked ?: 0
    LaunchedEffect(focus, asked) {
        if (focus == null || focus.served == asked) return@LaunchedEffect
        focus.served = asked
        val keyboard = input.inputMode == InputMode.Keyboard
        val exploring = context.getSystemService(AccessibilityManager::class.java)?.isTouchExplorationEnabled == true
        if (!keyboard && !exploring) return@LaunchedEffect
        if (!keyboard) touchFocus = true
        withFrameNanos { }                            // the button's focus target is attached after its first frame
        requester.requestFocus()
    }
    Column(
        modifier
            .fillMaxWidth()
            .padding(horizontal = t.spacing.gutter, vertical = t.space.s3),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        // takes no room in the zone (a 1 dp node would move the action by 1 dp)
        SbStatusRegion(announcedWork, Modifier.layout { measurable, constraints ->
            val p = measurable.measure(constraints)
            layout(0, 0) { p.place(0, 0) }
        })
        SbFailedOverAction(state, Modifier.fillMaxWidth(), action = {
            SbPrimaryAction(
                text,
                onClick,
                Modifier.fillMaxWidth().then(
                    if (focus == null) {
                        Modifier
                    } else {
                        Modifier
                            .focusRequester(requester)
                            .onFocusChanged {
                                if (it.isFocused) {
                                    hadFocus = true
                                } else if (hadFocus) {
                                    hadFocus = false
                                    touchFocus = false
                                }
                            }
                            .focusProperties { if (touchFocus) canFocus = true }
                    },
                ),
                icon,
                enabled,
                state,
                haptics,
            )
        }, hint = {
            if (hint != null) {
                Text(
                    hint,
                    style = SebaroTheme.typography.caption,
                    color = c.textMuted,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(top = t.space.s2),
                )
            }
        }) {
            if (state is SbActionState.Busy) {
                // Idle removes the callback; each cleanup entry registers after the app's normal back handler.
                sbBackKey(cancelling) {
                    BackHandler(enabled = !LocalSbBackLocked.current &&
                        (if (cancelling) cancelBackHeld else state.cancel != null)) {
                        if (!state.cancelling) state.cancel?.let { if (it.enabled) it.onCancel() }
                    }
                }
            }
            if (state is SbActionState.Busy && state.cancel != null && !LocalSbBackLocked.current) {
                val cancel = state.cancel
                SbSecondaryActionView(cancel.label, cancel.onCancel, Modifier.padding(top = t.space.s2), null,
                    cancel.enabled && !state.cancelling, false, t.space.s6, focusableWhenDisabled = true)   // 8 dp under the busy action
            } else if (secondaryAction != null) {
                Box(Modifier.padding(top = t.space.s2)) { secondaryAction() }
            }
        }

    }
}
